import os
import re
from html.parser import HTMLParser
from typing import List, Tuple

import deepl


class _HTMLChunkExtractor(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.parts: List[Tuple[str, str]] = []

    def handle_starttag(self, tag, attrs):
        attrs_text = "".join(
            f' {name}="{value}"' if value is not None else f" {name}"
            for name, value in attrs
        )
        self.parts.append(("tag", f"<{tag}{attrs_text}>"))

    def handle_startendtag(self, tag, attrs):
        attrs_text = "".join(
            f' {name}="{value}"' if value is not None else f" {name}"
            for name, value in attrs
        )
        self.parts.append(("tag", f"<{tag}{attrs_text}/>"))

    def handle_endtag(self, tag):
        self.parts.append(("tag", f"</{tag}>"))

    def handle_data(self, data):
        if data:
            self.parts.append(("text", data))

    def handle_comment(self, data):
        self.parts.append(("tag", f"<!--{data}-->"))

    def handle_decl(self, decl):
        self.parts.append(("tag", f"<!{decl}>"))

    def handle_entityref(self, name):
        self.parts.append(("text", f"&{name};"))

    def handle_charref(self, name):
        self.parts.append(("text", f"&#{name};"))


def _chunk_text(text: str, max_len: int = 2000) -> List[str]:
    if len(text) <= max_len:
        return [text]
    chunks = []
    start = 0
    while start < len(text):
        end = min(len(text), start + max_len)
        if end < len(text):
            split_at = text.rfind(" ", start, end)
            if split_at <= start:
                split_at = end
            end = split_at
        chunks.append(text[start:end])
        start = end
    return chunks


def translate_markup(html_or_markup: str, target_lang: str, source_lang: str = None) -> str:
    auth_key = os.environ.get("DEEPL_AUTH_KEY")
    if not auth_key:
        raise EnvironmentError("DEEPL_AUTH_KEY environment variable is required")

    translator = deepl.Translator(auth_key)
    parser = _HTMLChunkExtractor()
    parser.feed(html_or_markup)
    parser.close()

    translated_parts = []
    for kind, content in parser.parts:
        if kind == "tag":
            translated_parts.append(content)
            continue

        if not content.strip():
            translated_parts.append(content)
            continue

        translated_segments = []
        for segment in _chunk_text(content):
            result = translator.translate_text(
                segment,
                target_lang=target_lang,
                source_lang=source_lang,
                tag_handling="html",
                preserve_formatting=True,
            )
            translated_segments.append(result.text)
        translated_parts.append("".join(translated_segments))

    return "".join(translated_parts)
